  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Cancer is a complex, multilevel phenomenon [1-5] in which health outcomes depend on highly interrelated elements across stages of etiology, prevention, screening, diagnosis, treatment, survivorship, and end-of-life care [6, 7]. Standard bench and clinical research approaches alone are not well suited to account for this complexity, as most cancer control interventions often focus on explicit, often linear health outcomes of a specific, well-defined population [1, 8, 9]. The extent to which system dynamics modeling has been applied specifically to cancer prevention and control has not been studied.",
      "reason": "Describes current knowledge on cancer complexity and limitations of standard approaches, and identifies an important uncertainty or gap."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "To overcome persistent barriers to providing high-quality, equitable care, approaches are needed to address this complexity and provide guidance for successful intervention. The extent to which system dynamics modeling has been applied specifically to cancer prevention and control has not been studied.",
      "reason": "Explains the need for the review to address complexity and fill a knowledge gap in cancer prevention and control."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "past reviews in this field have noted a significant increase in their use since the early 2000s, especially in areas focused on chronic or non-communicable diseases [24, 25]. The extent to which system dynamics modeling has been applied specifically to cancer prevention and control has not been studied.",
      "reason": "Cites previous reviews and explains the need for the current review by highlighting the unstudied specific area of cancer prevention and control."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review is not specifically about intervention effects; it is a methods review focusing on system dynamics modeling applications."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review is not focused on complex interventions or delivery contexts in a way that requires a logic model; it is a systematic review of modeling methods."
    }
  ],
  "confidence": 90
